import path from "node:path";
import { installFromGithub } from "../../vessel.js";
import { installMopsDep } from "./install-mops-dep.js";
import { installLocalDep } from "./install-local-dep.js";
import { getRootDir } from "../../mops.js";
// install dependency
// returns false if failed
export async function installDep(dep, { verbose, silent, threads, ignoreTransitive } = {}, parentPkgPath) {
    if (dep.repo) {
        return installFromGithub(dep.name, dep.repo, {
            silent,
            verbose,
            ignoreTransitive,
        });
    }
    else if (dep.path) {
        let depPath = dep.path;
        parentPkgPath = parentPkgPath || getRootDir();
        if (parentPkgPath) {
            depPath = path.resolve(parentPkgPath, dep.path);
        }
        return installLocalDep(dep.name, depPath, {
            silent,
            verbose,
            ignoreTransitive,
        });
    }
    else if (dep.version) {
        return installMopsDep(dep.name, dep.version, {
            silent,
            verbose,
            threads,
            ignoreTransitive,
        });
    }
    console.warn(`Warning: dependency "${dep.name}" has no version, repo, or path`);
    return false;
}
